import mapa from '@/data/oficial/imagenes.json';
import { siteAsset } from '@/lib/asset-path';

/** Local copy of an image from the official site; `src` already carries the asset base. */
export type ImagenOficial = { src: string; w: number; h: number };

type Entrada = { src: string; w: number; h: number };

// Generated by scripts/oficial/imagenes.mjs: normalized official URL -> local WebP.
const MAPA = mapa as unknown as Record<string, Entrada>;

const HOST = 'www.tonysportselsalvador.com';

const ENTIDADES: Record<string, string> = { amp: '&', quot: '"', apos: "'", lt: '<', gt: '>', nbsp: ' ' };

function decodificarEntidades(texto: string): string {
  let salida = texto;
  // Twice, for double-encoded values such as "&amp;#038;".
  for (let i = 0; i < 2; i++) {
    salida = salida.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (entera, cuerpo: string) => {
      if (cuerpo[0] === '#') {
        const hex = cuerpo[1] === 'x' || cuerpo[1] === 'X';
        const codigo = hex ? parseInt(cuerpo.slice(2), 16) : parseInt(cuerpo.slice(1), 10);
        return Number.isFinite(codigo) && codigo > 0 && codigo <= 0x10ffff ? String.fromCodePoint(codigo) : entera;
      }
      return ENTIDADES[cuerpo.toLowerCase()] ?? entera;
    });
  }
  return salida;
}

function decodificarRuta(ruta: string): string {
  try {
    return decodeURI(ruta);
  } catch {
    return ruta;
  }
}

/**
 * Canonical form used as key in data/oficial/imagenes.json: https, www host,
 * no query/hash, HTML entities and percent-escapes decoded, Jetpack (i0/i1/i2.wp.com) unwrapped.
 * Non-URL values (data:, blob:, empty) are returned trimmed.
 */
export function normalizarUrlOficial(url: string): string {
  let s = decodificarEntidades(String(url ?? '').trim()).replace(/^['"]+|['"]+$/g, '').trim();
  if (!s) return '';
  if (/^(data|blob|mailto|tel|javascript):/i.test(s)) return s;
  if (s.startsWith('//')) s = `https:${s}`;
  else if (s.startsWith('/')) s = `https://${HOST}${s}`;
  else if (/^(www\.)?tonysportselsalvador\.com(\/|$)/i.test(s)) s = `https://${s}`;
  const partes = /^https?:\/\/([^/?#]+)([^?#]*)/i.exec(s);
  if (!partes) return s.replace(/[?#].*$/, '');
  let host = partes[1].toLowerCase().replace(/:(80|443)$/, '');
  let ruta = partes[2] || '/';
  if (/^i\d\.wp\.com$/.test(host)) {
    const envuelta = /^\/([^/]+)(\/.*)?$/.exec(ruta);
    if (envuelta) {
      host = envuelta[1].toLowerCase();
      ruta = envuelta[2] || '/';
    }
  }
  if (host === 'tonysportselsalvador.com') host = HOST;
  ruta = decodificarRuta(ruta).replace(/\/{2,}/g, '/');
  return `https://${host}${ruta}`;
}

// WordPress size variants: "foto-300x300.jpg", "foto-scaled.jpg", "foto-e1712345678.jpg".
function sinVariante(clave: string): string {
  let base = clave;
  for (let i = 0; i < 3; i++) {
    const siguiente = base.replace(/-(\d+x\d+|scaled|e\d{9,})(?=\.[a-z0-9]+$)/i, '');
    if (siguiente === base) break;
    base = siguiente;
  }
  return base;
}

let indiceVariantes: Map<string, Entrada> | null = null;

function porVariante(clave: string): Entrada | undefined {
  if (!indiceVariantes) {
    const indice = new Map<string, Entrada>();
    for (const [url, entrada] of Object.entries(MAPA)) {
      const base = sinVariante(url);
      const previa = indice.get(base);
      // The original upload wins; otherwise keep the widest mirrored variant.
      if (url === base) indice.set(base, entrada);
      else if (!MAPA[base] && (!previa || entrada.w > previa.w)) indice.set(base, entrada);
    }
    indiceVariantes = indice;
  }
  return indiceVariantes.get(sinVariante(clave));
}

function conBase(src: string): string {
  return src.startsWith('/assets/') ? siteAsset(src as `/assets/${string}`) : src;
}

/** Local WebP for an official image URL (any size variant), or null when it was not mirrored. */
export function imagenOficial(url?: string | null): ImagenOficial | null {
  if (!url) return null;
  const clave = normalizarUrlOficial(url);
  if (!clave) return null;
  const entrada = MAPA[clave] ?? porVariante(clave);
  if (!entrada) return null;
  return { src: conBase(entrada.src), w: entrada.w, h: entrada.h };
}

/** Local src for an official image URL; `fallback` (or '') when it was not mirrored. */
export function srcOficial(url?: string | null, fallback?: string): string {
  const imagen = imagenOficial(url);
  if (imagen) return imagen.src;
  return fallback ? conBase(fallback) : '';
}
